  `is_present` tinyint(1) DEFAULT '0',
  `is_absent` tinyint(1) DEFAULT '0',
  `is_half_day` tinyint(1) DEFAULT '0',
  `is_overtime` tinyint(1) DEFAULT '0',
  `ot_hours` decimal(5,2) DEFAULT '0.00',
  `is_holiday` tinyint(1) DEFAULT '0',
  `exception_flag` tinyint(1) DEFAULT '0',
  `exception_reason` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `approved_by` int(10) unsigned DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_att` (`employee_id`,`attendance_date`,`shift_id`),
