  CONSTRAINT `fk_att_shift` FOREIGN KEY (`shift_id`) REFERENCES `shifts` (`id`),
  CONSTRAINT `fk_att_vendor` FOREIGN KEY (`vendor_id`) REFERENCES `vendors` (`id`)
